import json

# Check all Mistral PW seeds for PID consistency with each other
pids_per_seed = {}
for seed in ['seed42', 'seed123', 'seed456', 'seed789']:
    path = f'results/multi_seed/mistral_pw_{seed}/results.json'
    with open(path) as f:
        data = json.load(f)
    results = data['results']
    pids = set(d['problem_id'] for d in results)
    pids_per_seed[seed] = pids
    print(f'{seed}: N={len(results)}, unique PIDs={len(pids)}')

# Cross-check
for s1 in pids_per_seed:
    for s2 in pids_per_seed:
        if s1 < s2:
            diff1 = pids_per_seed[s1] - pids_per_seed[s2]
            diff2 = pids_per_seed[s2] - pids_per_seed[s1]
            if diff1 or diff2:
                print(f'{s1} vs {s2}: {len(diff1)} in {s1} only, {len(diff2)} in {s2} only')
                for pid in sorted(diff1):
                    print(f'  {s1} only: {pid}')
                for pid in sorted(diff2):
                    print(f'  {s2} only: {pid}')
            else:
                print(f'{s1} vs {s2}: identical')
"
